159	// detectTimezone returns a best-effort timezone name for the current host.
160	// Order: $TZ → /etc/localtime symlink → time.Local → "UTC" as last resort.
161	// A candidate that fails normalization is skipped (not forwarded, not coerced
162	// to UTC), so a bogus $TZ on a correctly-configured box still yields the
163	// system timezone from /etc/localtime. The server is the canonical authority
164	// for what counts as a valid zone and falls back to UTC for anything it
165	// doesn't recognize, so we only do enough validation to avoid sending
166	// obvious garbage (paths, POSIX forms Go can't load, the "Local" sentinel).
167	func detectTimezone() string {
168		if tz := normalizeTimezone(os.Getenv("TZ")); tz != "" {
169			return tz
170		}
171		if link, err := os.Readlink("/etc/localtime"); err == nil {
172			if tz := normalizeTimezone(link); tz != "" {
173				return tz
174			}
175		}
176		if tz := normalizeTimezone(time.Local.String()); tz != "" {
177			return tz
178		}
179		return "UTC"
180	}
181	
182	// normalizeTimezone returns a name Go can load as a time zone, or "" if the
183	// input can't be resolved. It strips the POSIX ":" prefix and zoneinfo path
184	// prefix, then requires time.LoadLocation to succeed.
185	//
186	// This is not strict IANA-only validation: Go's LoadLocation accepts legacy
187	// aliases like EST5EDT, GMT0, and PST8PDT in addition to Area/Location
188	// names. Those may or may not be canonically understood by the server — if
189	// the server doesn't recognize one, it falls back to UTC on its end. We
190	// accept that mild mis-bucketing risk as the price of a simple check that
191	// catches the common failure modes (paths, unknown POSIX forms like UTC0,
192	// typos, the "Local" sentinel).
193	func normalizeTimezone(raw string) string {
194		name := strings.TrimPrefix(raw, ":")
195		const marker = "/zoneinfo/"
196		if idx := strings.LastIndex(name, marker); idx >= 0 {
197			name = name[idx+len(marker):]
198		}
199		if name == "" || name == "Local" {
200			return ""
201		}
202		if _, err := time.LoadLocation(name); err != nil {
203			return ""
204		}
205		return name
206	}
