208	func groupCommitsByDay(commits []userCommit) []commitDay {
209		byDate := make(map[string][]userCommit)
210		var dateOrder []string
211	
212		for _, c := range commits {
213			date := dateUnknown
214			if c.CommitDate != nil {
215				if t, err := parseFlexibleTime(*c.CommitDate); err == nil {
216					date = t.Local().Format("2006-01-02")
217				}
218			}
219			if _, exists := byDate[date]; !exists {
220				dateOrder = append(dateOrder, date)
221			}
222			byDate[date] = append(byDate[date], c)
223		}
224	
225		// Sort dates newest first, with unknown dates pushed to the end
226		sort.Slice(dateOrder, func(i, j int) bool {
227			if dateOrder[i] == dateUnknown {
228				return false
229			}
230			if dateOrder[j] == dateUnknown {
231				return true
232			}
233			return dateOrder[i] > dateOrder[j]
234		})
235	
236		result := make([]commitDay, 0, len(dateOrder))
237		for _, d := range dateOrder {
238			result = append(result, commitDay{Date: d, Commits: byDate[d]})
239		}
240		return result
241	}
